// Unsent presentation state only. Restoring a draft never sends a message.
let composerDraftOwner=null;
let composerDraftRestoring=false;
function composerDraftKey(note){return 'nb-composer-v1/'+JSON.stringify([api.ship,note])}
function composerDraftWarning(text){
  let el=document.getElementById('composerDraftWarning');
  if(!el){el=document.createElement('div');el.id='composerDraftWarning';el.setAttribute('role','status');document.getElementById('chatInputArea').appendChild(el)}
  el.textContent=text;el.hidden=!text;
}
function saveComposerDraft(){
  const input=document.getElementById('chatInput');
  if(composerDraftRestoring||!input||!composerDraftOwner||composerDraftOwner!==composerDraftKey(state.currentNoteId))return true;
  try{
    if(!input.value)localStorage.removeItem(composerDraftOwner);
    else localStorage.setItem(composerDraftOwner,JSON.stringify({version:1,text:input.value,
      replyingTo:state.replyingTo??null,replyingToEid:state.replyingToEid??null,
      editingMsgId:state.editingMsgId??null,editingEid:state.editingEid??null,
      replyLabel:document.getElementById('replyLabel').textContent||''}));
    composerDraftWarning('');return true;
  }catch(e){composerDraftWarning('Draft could not be saved on this device. Copy your text before closing.');return false}
}
function readComposerDraft(note){
  const key=composerDraftKey(note);let draft=null;
  {
    const raw=localStorage.getItem(key);
    if(raw!==null){
      draft=JSON.parse(raw);
      const ref=x=>x===null||typeof x==='string'||Number.isSafeInteger(x);
      if(!draft||draft.version!==1||typeof draft.text!=='string'||typeof draft.replyLabel!=='string'||
        !['replyingTo','replyingToEid','editingMsgId','editingEid'].every(k=>ref(draft[k])))throw Error('Invalid draft');
    }
  }
  return draft;
}
function restoreComposerDraft(note,draft){
  const input=document.getElementById('chatInput');if(!input)return;
  if(arguments.length<2)draft=readComposerDraft(note);
  const key=composerDraftKey(note);
  composerDraftRestoring=true;
  try{
    input.value=draft?draft.text:'';
    for(const key of ['replyingTo','replyingToEid','editingMsgId','editingEid'])state[key]=draft?draft[key]:null;
    const replying=state.replyingTo!==null||state.replyingToEid!==null;
    document.getElementById('replyLabel').textContent=replying?draft.replyLabel:'';
    document.getElementById('replyBar').classList.toggle('visible',replying);
    input.placeholder=state.editingMsgId!==null?'editing message... (Esc to cancel)':'message...';
    composerDraftOwner=key;autoResize(input);updateInputMirror();composerDraftWarning('');
  }finally{composerDraftRestoring=false}
  return true;
}
window.addEventListener('pagehide',saveComposerDraft);

